if found then if r is distinct from to_jsonb(jsonb_populate_record(null::catalog_work_descriptions,'{"work_id":1372,"language":"en","bound_author_id":157,"text":"A decade after leading a revolution, Darrow still faces a war that refuses to end. The society he helped overturn has left a fragile new order, and another dangerous mission threatens everything he hoped to protect. Elsewhere, a young refugee, a grieving former soldier and an heir seeking revenge confront the consequences of that struggle. Their paths broaden the story beyond Darrow as the promises of liberation collide with the costs of continuing conflict.","source_type":"official_publisher","source_name":"Hachette UK / Hodder & Stoughton","source_url":"https://www.hachette.co.uk/titles/pierce-brown/iron-gold/9781473646582/","evidence":[{"url":"https://www.hachette.co.uk/titles/pierce-brown/iron-gold/9781473646582/","checked_at":"2026-11-08T20:42:50Z","identity":"Work, author and exact English ISBN checked separately; synopsis concerns this novel.","secondary":null}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-08T20:48:00Z","review_batch":"source-repair-20261108"}'::jsonb)) then raise exception 'Existing summary conflict 1372';end if;
else insert into catalog_work_descriptions select * from jsonb_populate_record(null::catalog_work_descriptions,'{"work_id":1372,"language":"en","bound_author_id":157,"text":"A decade after leading a revolution, Darrow still faces a war that refuses to end. The society he helped overturn has left a fragile new order, and another dangerous mission threatens everything he hoped to protect. Elsewhere, a young refugee, a grieving former soldier and an heir seeking revenge confront the consequences of that struggle. Their paths broaden the story beyond Darrow as the promises of liberation collide with the costs of continuing conflict.","source_type":"official_publisher","source_name":"Hachette UK / Hodder & Stoughton","source_url":"https://www.hachette.co.uk/titles/pierce-brown/iron-gold/9781473646582/","evidence":[{"url":"https://www.hachette.co.uk/titles/pierce-brown/iron-gold/9781473646582/","checked_at":"2026-11-08T20:42:50Z","identity":"Work, author and exact English ISBN checked separately; synopsis concerns this novel.","secondary":null}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-08T20:48:00Z","review_batch":"source-repair-20261108"}'::jsonb);end if;
select to_jsonb(d) into r from catalog_work_descriptions d where work_id=4864 and language='en' for update;
if found then if r is distinct from to_jsonb(jsonb_populate_record(null::catalog_work_descriptions,'{"work_id":4864,"language":"en","bound_author_id":2537,"text":"Lena has escaped a society that treats love as an illness, but freedom brings loss and unfamiliar dangers. Separated from Alex, she finds shelter among people resisting the authorities and begins to take part in their struggle. The second Delirium novel follows her efforts to survive beyond the world she knew and to find a place within the resistance. Her grief and new relationships complicate the choices she faces as that conflict draws her further in.","source_type":"official_catalog","source_name":"Richland Library / Wake County Public Libraries","source_url":"https://www.richlandlibrary.com/catalog/detail/1656511","evidence":[{"url":"https://www.richlandlibrary.com/catalog/detail/1656511","checked_at":"2026-11-08T20:42:50Z","identity":"Work, author and exact English ISBN checked separately; synopsis concerns this novel.","secondary":"https://catalog.wake.gov/Record/627298"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-08T20:48:00Z","review_batch":"source-repair-20261108"}'::jsonb)) then raise exception 'Existing summary conflict 4864';end if;
else insert into catalog_work_descriptions select * from jsonb_populate_record(null::catalog_work_descriptions,'{"work_id":4864,"language":"en","bound_author_id":2537,"text":"Lena has escaped a society that treats love as an illness, but freedom brings loss and unfamiliar dangers. Separated from Alex, she finds shelter among people resisting the authorities and begins to take part in their struggle. The second Delirium novel follows her efforts to survive beyond the world she knew and to find a place within the resistance. Her grief and new relationships complicate the choices she faces as that conflict draws her further in.","source_type":"official_catalog","source_name":"Richland Library / Wake County Public Libraries","source_url":"https://www.richlandlibrary.com/catalog/detail/1656511","evidence":[{"url":"https://www.richlandlibrary.com/catalog/detail/1656511","checked_at":"2026-11-08T20:42:50Z","identity":"Work, author and exact English ISBN checked separately; synopsis concerns this novel.","secondary":"https://catalog.wake.gov/Record/627298"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-08T20:48:00Z","review_batch":"source-repair-20261108"}'::jsonb);end if;
select to_jsonb(s) into r from catalog_description_snapshots s where work_id=4864 and edition_id=5023 and locale='en' for update;
if not found then raise exception 'Expected provider snapshot absent';end if;
if r->>'provider_status'<>'withdrawn' then
if r is distinct from to_jsonb(jsonb_populate_record(null::catalog_description_snapshots,'{"work_id":4864,"edition_id":5023,"locale":"en","binding_hash":"9a33e9cf57aa0dfd912ac0ac311e34e12437ca17cbc7672a41461f17cbce4c57","bound_author_id":2537,"bound_title":"Pandemonium","bound_language":"eng","bound_isbn13":"9780061978067","bound_open_library_work_id":"OL16286212W","text":"In an alternate United States, love has been declared a dangerous disease, and the government forces everyone who reaches eighteen to have a procedure called the Cure. Living with her aunt, uncle, and cousins in Portland, Maine, Lena Haloway is very much looking forward to being cured and living a safe, predictable life. She watched love destroy her mother and isn''t about to make the same mistakes.\n\nBut with ninety-five days left until her treatment, Lena meets enigmatic Alex, a boy from the Wilds who lives under the government''s radar. What will happen if they do the unthinkable and fall in love?","source_key":"OL25104675M","fetched_at":"2026-11-08T20:02:54.647+00:00","checked_at":"2026-11-08T20:02:54.648+00:00","provider_status":"resolved","validation":"identity_and_language_verified"}'::jsonb)) then raise exception 'Snapshot changed since review';end if;
